const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const stamp = `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}-${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
const rand = Math.random().toString(36).slice(2, 6);
const rgName = `n8n-rg-${stamp}-${rand}`;
const location = 'eastus';

return [{
  json: {
    rgName,
    location,
    generatedAt: now.toISOString()
  }
}];

const sshOut = $input.first().json;
const gen = $('Generate Unique Resource Group Name').first().json;

return [{
  json: {
    status: 'SUCCESS',
    resourceGroup: gen.rgName,
    location: gen.location,
    generatedAt: gen.generatedAt,
    output: (sshOut.stdout || '').trim(),
    message: `[n8n] Created Azure resource group '${gen.rgName}' in '${gen.location}' via az cli on Worker1OL`
  }
}];
